#!/usr/bin/env python3
import json
L = [71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64
S = set(L)
triples = []
for i, a in enumerate(L):
    for b in L[i+1:]:
        c = a + b
        if c in S and c != a and c != b:
            triples.append((a, b, c))
from collections import defaultdict
num_to_triples = defaultdict(list)
for t in triples:
    for n in t:
        num_to_triples[n].append(t)
used = set()
solution = []
nums = sorted(L, key=lambda n: len(num_to_triples[n]))
def backtrack():
    if len(used) == len(L):
        return True
    for n in nums:
        if n not in used:
            target = n
            break
    for t in num_to_triples[target]:
        a, b, c = t
        if a in used or b in used or c in used:
            continue
        used.update([a, b, c])
        solution.append(t)
        if backtrack():
            return True
        used.difference_update([a, b, c])
        solution.pop()
    return False
if backtrack():
    for a, b, c in solution:
        print(f"({a}, {b}, {c})")
    witness = {"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": {"partition": solution}}
    print("WITNESS: " + json.dumps(witness))
else:
    witness = {"polarity": "negative", "evidence": {"path": "execution://witness"}, "argument": "No partition exists for the given list."}
    print("WITNESS: " + json.dumps(witness))
